def main():
 p=HERE/'prompts';p.mkdir(exist_ok=True)
 jobs={}
 for name,(size,alpha,subject) in JOBS.items():
  (p/f'{name}.prompt').write_text(LOCK+'\nUse case: illustration-story.\n'+REF+subject+(CUT if alpha else '')+'\n',encoding='utf-8')
  jobs[name]={'model':'gpt-image-2.6-sunburst','endpoint':'images.edits','reference':'key-art.png','size':size,'quality':'high','background':'transparent' if alpha else 'opaque','raw_output':f'src/output/imagegen/{name}.png'}
 (p/'jobs.json').write_text(json.dumps(jobs,indent=2)+'\n',encoding='utf-8')
 print(len(jobs),'explicit-model asset prompts written.')
if __name__=='__main__':main()
